INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(9, 'koKR', 'Pola śmierci', 'Popatrz tylko, co się stało z tym miejscem! Kiedyś mieszkali na tych ziemiach porządni rolnicy. Ale przeklęci złodzieje wszystkich przegonili. Tylko nie mnie! Wygląda jednak na to, że pola opanowały zbożowe wartowniki.$b$bJeśli masz ochotę na robotę, chciałbym, żebyś $gposzedł:poszła; i $gzniszczył:zniszczyła; dwadzieścia sztuk. Wróć, jak skończysz, to dostaniesz zapłatę. A jak uporasz się z tymi na moim polu, oczyść też pola sąsiadów.', 'Rolnik Saldean chce, żebyś $gzniszczył:zniszczyła; 20 zbożowych wartowników.', '', 'Wróć do rolnika Saldeana na Farmę Saldeana w Zachodnim Skraju.', '', '', '', '', 0),
(12, 'koKR', 'Milicja Ludowa', 'Milicja Ludowa ma tylko jeden cel: bronić ziem Zachodniego Skraju i przywrócić pokój w naszej okolicy. Niestety, ceną pokoju często jest krew.$b$bJeden z moich zwiadowców przyniósł wieść o bandzie traperów Nieskornych, którzy sieją spustoszenie w pobliżu. Dostaję raporty, że widziano ich przy Kopalni Jangolode na północnym zachodzie, a także na Farmie Molsenów i na dyniowej farmie Furlbrowów. Jeśli chcesz wstąpić w nasze szeregi, zabij 15 traperów Nieskornych i 15 przemytników Nieskornych, a potem wróć do mnie.', 'Gryan Mocnopłaszcz chce, żebyś $gzabił:zabiła; 15 traperów Nieskornych i 15 przemytników Nieskornych, a potem $gwrócił:wróciła; do niego na Wzgórze Strażnicze.', '', 'Wróć do Gryana Mocnopłaszcza na Wzgórze Strażnicze w Zachodnim Skraju.', '', '', '', '', 0),
(13, 'koKR', 'Milicja Ludowa', 'Widziano bandę okrutnych łupieżców Nieskornych, którzy plądrują Kamieniołom Złotego Wybrzeża, Księżycowy Potok i Gospodarstwo Alexstona. Milicja Ludowa nie będzie tego tolerować. Ruszaj natychmiast, $n, i niech Zachodni Skraj poczuje obecność Światła.$b$bKamieniołom Złotego Wybrzeża leży blisko brzegu, na zachód od wieży. W ramach kolejnego etapu szkolenia masz zabić 15 tych plugawych łupieżców Nieskornych i 15 szabrowników Nieskornych.', 'Gryan Mocnopłaszcz chce, żebyś $gzabił:zabiła; 15 łupieżców Nieskornych i 15 szabrowników Nieskornych, a potem $gwrócił:wróciła; do niego na Wzgórze Strażnicze.', '', 'Wróć do Gryana Mocnopłaszcza na Wzgórze Strażnicze w Zachodnim Skraju.', '', '', '', '', 0),
(14, 'koKR', 'Milicja Ludowa', 'Części Nieskornych udało się nam wymknąć. Mój najbardziej zaufany zwiadowca donosi, że ci Nieskorni łupią i plądrują okolicę aż po południowy Zachodni Skraj. Sądzimy, że ukrywają się na Wzgórzach Sztyletów i planują kolejny ruch. Zgładź tych nędzników w imię Milicji Ludowej.', 'Gryan Mocnopłaszcz chce, żebyś $gzabił:zabiła; 15 rozbójników Nieskornych, 5 czatowników Nieskornych i 5 pięściarzy Nieskornych, a potem $gwrócił:wróciła; do niego na Wzgórze Strażnicze.', '', 'Wróć do Gryana Mocnopłaszcza na Wzgórze Strażnicze w Zachodnim Skraju.', '', '', '', '', 0),
(22, 'koKR', 'Placek z wątróbki krwawokła', 'Cebula obrana. Czosnek posiekany. Rozmaryn roztarty. Spód upieczony. Koperek pokrojony. Sos się dusi. Teraz do mojego słynnego placka z mięsem brakuje mi już tylko 8 wątróbek krwawokła!', 'Salma Saldean potrzebuje 8 wątróbek krwawokła, żeby upiec placek z wątróbki krwawokła.', '', 'Wróć do Salmy Saldean na Farmę Saldeana w Zachodnim Skraju.', '', '', '', '', 0),
(36, 'koKR', 'Gulasz z Zachodniego Skraju', 'Nigdy nie myślałam, że przyjdzie dzień, kiedy opuszczę farmę. Ale na polach roi się od złodziei i jest tu dla nas o wiele za niebezpiecznie. Jak tylko rolnik Furlbrow naprawi wóz, ruszamy w drogę.$b$bMoże zrobisz mi przysługę? Zaraz nabazgram swój przepis na gulasz z Zachodniego Skraju. Zanieś go, proszę, Salmie Saldean, na tamtą farmę. Farma Saldeanów jest zaraz za rozwidleniem drogi.', 'Verna Furlbrow chce, żebyś $gdostarczył:dostarczyła; jej przepis na gulasz z Zachodniego Skraju Salmie Saldean.', '', '', '', '', '', '', 0),
(38, 'koKR', 'Gulasz z Zachodniego Skraju', 'Pomóż mi ugotować gulasz z Zachodniego Skraju! Przynieś mi takie składniki:$b$b3 łykowate mięsa sępa$b3 ryje krwawokła$b3 oczy murloka$b3 okry', 'Salma Saldean chce 3 łykowate mięsa sępa, 3 ryje krwawokła, 3 oczy murloka i 3 okry.', '', 'Wróć do Salmy Saldean na Farmę Saldeana w Zachodnim Skraju.', '', '', '', '', 0),
(48, 'koKR', 'Słodki bursztyn', 'Tam, gdzie na południu winorośl się wije,$bstudnia ukryta głęboko wodę kryje.$bCzysta jak Światła córa, co w bieli stoi –$bprzynieś mi świętej wody źródlanej, co ducha koi.', 'Przynieś świętą wodę źródlaną Grimbooze\'owi Gromowarowi.', '', 'Wróć do Grimbooze\'a Gromowara na Wzgórza Sztyletów w Zachodnim Skraju.', '', '', '', '', 0),
(49, 'koKR', 'Słodki bursztyn', 'Bursztyn – barwa mej najdłuższej miłości,$bjak ostatni żar zmierzchu, gdy noc w niebie gości.$bBy miłość ma mogła doczekać się narodzenia,$bprzynieś mi po worku żyta, kukurydzy i jęczmienia.', 'Grimbooze Gromowar chce worek jęczmienia, worek żyta i worek kukurydzy.', '', 'Wróć do Grimbooze\'a Gromowara na Wzgórza Sztyletów w Zachodnim Skraju.', '', '', '', '', 0),
(50, 'koKR', 'Słodki bursztyn', 'Będę mieszał i mieszał, aż zacier gotowy,$bna nasz własny zapasik, tajny i domowy.$bZ mocnego metalu destylatora nam trzeba,$bprzynieś srebrytu, a pieśń ma wzleci do nieba!', 'Grimbooze Gromowar chce srebrytu.', '', 'Wróć do Grimbooze\'a Gromowara na Wzgórza Sztyletów w Zachodnim Skraju.', '', '', '', '', 0),
(51, 'koKR', 'Słodki bursztyn', 'Świeżo pędzony, lecz jeszcze nie cedzony,$bjak ugór zaorany, na ziarno spragniony.$bTeraz z węgla drzewnego stos przygotuję,$bprzynieś mi gałąź jaworu – tego potrzebuję.', 'Przynieś gałąź jaworu Grimbooze\'owi Gromowarowi.', '', 'Wróć do Grimbooze\'a Gromowara na Wzgórza Sztyletów w Zachodnim Skraju.', '', '', '', '', 0),
(53, 'koKR', 'Słodki bursztyn', 'Płyn słodki jak miód, jak łzy dziecka przejrzysty,$bz latami nabiera barwy bursztynu, złocisty.$bLecz nim się upijemy, aż zaszumi w głowie,$bbeczkę z dębu zwęglonego zbić trzeba – ja ci to mówię!', 'Przynieś Grimbooze\'owi Gromowarowi wiązkę zwęglonego dębu.', '', 'Wróć do Grimbooze\'a Gromowara na Wzgórza Sztyletów w Zachodnim Skraju.', '', '', '', '', 0),
(64, 'koKR', 'Zapomniana pamiątka rodzinna', 'To było straszne! Verna mnie obudziła, jak usłyszała hałas na polach. Na polach było pełno chuliganów. Uciekaliśmy w pośpiechu i zapomniałem zabrać zegarek kieszonkowy. Ojciec Verny dał mi go w dniu naszego ślubu i aż mi niedobrze, jak pomyślę, że mają go te złodzieje. Zostawiłem zegarek w szafie w domu na farmie. Szukaj pola dyń na zachodzie – nie da się go przegapić. Jak mi go przyniesiesz, będę ci naprawdę wdzięczny!', 'Rolnik Furlbrow chce, żebyś $godzyskał:odzyskała; jego zegarek kieszonkowy z szafy w jego domu na dyniowej farmie na zachodzie.', '', 'Wróć do rolnika Furlbrowa w Zagrodzie Jansenów w Zachodnim Skraju.', '', '', '', '', 0),
(102, 'koKR', 'Patrol w Zachodnim Skraju', 'Wichrogród nas porzucił. Po równinach Zachodniego Skraju hula plugawy wiatr zepsucia. To moja ojczyzna i nie odwrócę się plecami do mieszkańców, którzy postanowili tu zostać. My, dawni rolnicy, stawimy opór.$b$bTwoje zadanie, jeśli zechcesz je przyjąć, to patrolować łąki Zachodniego Skraju. Wytrop i zabij podłe gnole, które najwyraźniej współpracują ze złodziejami z Martwej Kopalni. Przynieś mi osiem łap gnoli, a nagrodzę twoją odwagę.', 'Przynieś 8 łap gnoli kapitanowi Danuvinowi na Wzgórze Strażnicze.', '', 'Wróć do kapitana Danuvina na Wzgórze Strażnicze w Zachodnim Skraju.', '', '', '', '', 0),
(103, 'koKR', 'Strażnik płomienia', 'Noc, w której zginęła rodzina latarnika, była straszna. Bezradnie patrzyłem, jak Stary Mętnooki prowadzi atak. Ale co się stało, to się nie odstanie, a teraz martwię się o życie marynarzy na Wielkim Morzu, których statki podpływają blisko zdradliwych skał wybrzeża. Skoro nie ma nikogo, kto czuwałby nad płomieniem, odpowiedzialność spadła na mnie.$b$bPomóż mi utrzymać ogień w latarni – przynieś mi 5 flaszek oleju ze zbożowych potworów.', 'Przynieś 5 flaszek oleju kapitanowi Graysonowi do Latarni Zachodniego Skraju.', '', 'Wróć do kapitana Graysona do Latarni Zachodniego Skraju w Zachodnim Skraju.', '', '', '', '', 0),
(104, 'koKR', 'Postrach wybrzeża', 'Kiedy moje życie skończyło się na skałach, nie miałem pojęcia, co czeka mnie po śmierci. Tamtej nocy latarnia była ciemna, bo Stary Mętnooki przepłoszył rodzinę latarnika. Wrócili i znów rozpalili ogień, ale Stary Mętnooki namówił słabsze umysłem murloki, by jeszcze raz napadły z nim na latarnię. Za drugim razem rodzina nie miała tyle szczęścia i zginęła bezradnie na moich oczach.$b$bJeśli zobaczysz Starego Mętnookiego na brzegu, zabij go i przynieś mi jedną z jego łusek, a cię nagrodzę.', 'Przynieś łuskę Starego Mętnookiego kapitanowi Graysonowi do Latarni Zachodniego Skraju.', '', 'Wróć do kapitana Graysona do Latarni Zachodniego Skraju w Zachodnim Skraju.', '', '', '', '', 0),
(117, 'koKR', 'Lager Gromowarów', 'Pośpiesz się, $gprzyjacielu:przyjaciółko;, żwawo, bez zwłoki,$bby nasz lager miał smak pełny, głęboki.$bMniej jak gulasz, a bardziej jak piwo –$bpo chmiel ruszaj więc żwawo i żywo!', 'Przynieś Grimbooze\'owi Gromowarowi 5 porcji chmielu, żeby mógł dokończyć swój wyjątkowy trunek.', '', 'Wróć do Grimbooze\'a Gromowara na Wzgórza Sztyletów w Zachodnim Skraju.', '', '', '', '', 0),
(136, 'koKR', 'Ukryty skarb kapitana Sandersa', 'Jeśli to czytasz, znaczy, że stary kapitan Sanders leży w wodnym grobie. A więc mój skarb jest teraz twój, musisz tylko iść za wskazówkami.$b$bNajpierw znajdź mój kufer. Pewnie jest już do połowy zakopany w piasku, gdzieś na zachodnim wybrzeżu Zachodniego Skraju, przy wraku statku. Wraków tam od groma, ale zardzewiała kotwica na brzegu jest tylko jedna. Znajdź tę kotwicę, a znajdziesz mój kufer! Tam szukaj następnej wskazówki.', 'Znajdź kufer kapitana Sandersa i przeszukaj go w poszukiwaniu następnej wskazówki.', '', '', '', '', '', '', 0),
(138, 'koKR', 'Ukryty skarb kapitana Sandersa', 'Wskazówka do skarbu brzmi: Dobra robota, kamracie! Teraz musisz iść prosto na wschód. Na wschód, w górę urwisk, na wschód, aż do drogi. Szukaj ruin starego komina przy drodze. Znajdziesz tam starą beczkę z następną wskazówką.', 'Znajdź starą beczkę przy zrujnowanym kominie i przeszukaj ją w poszukiwaniu następnej wskazówki.', '', '', '', '', '', '', 0),
(139, 'koKR', 'Ukryty skarb kapitana Sandersa', 'Przeszukując beczkę, znajdujesz kolejny kawałek pergaminu. Ten brzmi: A teraz od tej beczki zwróć się na północ. Idź prosto jak strzelił, aż zobaczysz pusty dzban przy samotnym wiatraku na nadmorskich urwiskach. Jak pogrzebiesz przy tym dzbanie, może znajdziesz to, czego szukasz.', 'Przeszukaj pusty dzban przy wiatraku w poszukiwaniu następnej wskazówki.', '', '', '', '', '', '', 0),
(140, 'koKR', 'Ukryty skarb kapitana Sandersa', 'I rzeczywiście, głęboko w starym dzbanie tkwi kolejna wskazówka do skarbu Sandersa. W kilku miejscach atrament się rozmazał, a papier cuchnie whisky, ale część tekstu da się odczytać: Skoro już znalazłeś mój stary dzban po whisky, skarb jest tuż-tuż! Od butelki zwróć się na zachód i zejdź na brzeg. Jak dojdziesz do wody, nie zatrzymuj się! Płyń prosto na zachód, aż znajdziesz wyspę z moją skrzynią ze skarbem!', 'Znajdź skrzynię kapitana Sandersa i otwórz ją, by odebrać nagrodę.', '', '', '', '', '', '', 0),
(143, 'koKR', 'Posłaniec do Zachodniego Skraju', 'Z Armią Wichrogrodu dzieje się coś dziwnego. Powinni tu już być w pełnej sile. Ale czas to luksus, na który nie możemy sobie pozwolić. Nie będę bezczynnie patrzył, jak mieszkańcy Jeziernych Włości oddają życie, nie próbując sprowadzić pomocy. Słyszałem, że w Zachodnim Skraju formuje się milicja ludowa.$b$bZanieś tę prośbę jej przywódcy, Gryanowi Mocnopłaszczowi. Może ludzie Mocnopłaszcza udzielą nam wsparcia, dopóki król nie przyśle posiłków.', 'Sędzia Solomon chce, żebyś $gzaniósł:zaniosła; jego pisemną prośbę Gryanowi Mocnopłaszczowi w Zachodnim Skraju.', '', '', '', '', '', '', 0),
(144, 'koKR', 'Posłaniec do Zachodniego Skraju', 'Z bólem czytam list sędziego Solomona. Ale najwyraźniej nie ma on pojęcia o wojnie, jaka toczy się w Zachodnim Skraju, bo inaczej nie oczekiwałby pomocy od Milicji. Gdyby Wichrogród nie porzucił także nas, Milicja nie byłaby nam potrzebna.$b$bZanieś tę odpowiedź swojemu zwierzchnikowi w Rudej Grani, $N. I przekaż mu, że serce mi krwawi po stracie dobrych ludzi.', 'Wróć do sędziego Solomona z odpowiedzią Gryana Mocnopłaszcza.', '', '', '', '', '', '', 0),
(151, 'koKR', 'Biedna Stara Siwka', 'Biedna Stara Siwka! Taka zmęczona po całej tej pracy, którą jej zadawaliśmy. Nakarmiłam ją, zanim opuściliśmy farmę, ale nie spodziewaliśmy się, że wóz nam się zepsuje. Jeśli $gmógłbyś:mogłabyś; przynieść jej kilka garści owsa z pól, byłabym wdzięczna.$B$BZałożę się, że znajdziesz trochę przy wszystkich farmach w Zachodnim Skraju, jeśli tylko ominiesz te okropne maszyny, które się tam zadomowiły. Na południowy zachód stąd jest kilka farm.', 'Verna Furlbrow z Zachodniego Skraju chce, żebyś $gprzyniósł:przyniosła; jej 8 garści owsa.', '', 'Wróć do Verny Furlbrow w Zagrodzie Jansenów w Zachodnim Skraju.', '', '', '', '', 0),
(152, 'koKR', 'Wybrzeże nie jest bezpieczne', 'Pewnie $gzauważyłeś:zauważyłaś; te wszystkie wraki wzdłuż wybrzeża. Wielkie Morze jest naprawdę zdradliwe. Wybrzeże Zachodniego Skraju trzeba utrzymać w bezpieczeństwie, żeby marynarze, którzy trafią na nasze plaże, byli bezpieczni. Ale murloki sprawiają kłopoty.$b$bZabij 7 łowców fal, 7 wojowników, 7 wyroczni i 7 przybrzeżników, a dopilnuję, żebyś $gzostał nagrodzony:została nagrodzona;.', 'Zabij 7 łowców fal, 7 wojowników, 7 wyroczni i 7 przybrzeżników, a potem wróć do kapitana Graysona do Latarni Zachodniego Skraju.', '', 'Wróć do kapitana Graysona do Latarni Zachodniego Skraju w Zachodnim Skraju.', '', '', '', '', 0),
(153, 'koKR', 'Czerwone skórzane chusty', 'Front Nieskornych ciągle się przesuwa. Od dłuższego czasu śledzę ich ruchy. Przy okazji ustaliłem, że wielu członków bandy można rozpoznać po czerwonych skórzanych chustach, które noszą.$b$bPrzynieś mi 15 takich chust, a dopilnuję, żebyś $gdostał:dostała; nagrodę.', 'Przynieś 15 czerwonych skórzanych chust zwiadowcy Galiaanowi na Wzgórze Strażnicze.', '', 'Wróć do zwiadowcy Galiaana na Wzgórze Strażnicze w Zachodnim Skraju.', '', '', '', '', 0),
(184, 'koKR', 'Akt własności Furlbrowa', 'To akt własności rozległych pól uprawnych w Zachodnim Skraju. Podpisał go niejaki Theodore Furlbrow, a współpodpisała jego żona Verna. Na odwrocie aktu ktoś pośpiesznie nabazgrał:$B$B„Przycisnęliśmy Furlbrowa i zabraliśmy mu akt. Pomyślałem, że się przyda, jakbyś chciał podrobić taki na własne gospodarstwo.$B$BFurlbrowowie nie będą nam robić kłopotów. Jak ich ostatnio widziałem, wynosili się z Zachodniego Skraju i utknęli z połamanym wozem”.$B$BMyślisz, że Furlbrowowie pewnie chcieliby odzyskać swój akt...', 'Zanieś akt własności Furlbrowa rolnikowi Furlbrowowi.', '', '', '', '', '', '', 0),
(214, 'koKR', 'Czerwone jedwabne chusty', 'Nie jest tajemnicą, że znakiem rozpoznawczym bandy Nieskornych są czerwone chusty. Ale dowiedzieliśmy się, że materiał, z którego są zrobione, świadczy o randze członka bandy.$b$bDlatego chcę, żebyś $gwyeliminował:wyeliminowała; jak najwięcej wysoko postawionych Nieskornych. Najwyżej postawionych członków bez wątpienia znajdziesz w tajnej kryjówce VanCleefa. Gdy skończysz, przynieś mi 10 czerwonych jedwabnych chust jako dowód ich śmierci, a nagrodzę cię. Powodzenia, $N.', 'Zwiadowczyni Riell w wieży na Wzgórzu Strażniczym chce, żebyś $gprzyniósł:przyniosła; jej 10 czerwonych jedwabnych chust.', '', 'Wróć do zwiadowczyni Riell w Zachodnim Skraju.', '', '', '', '', 0),
(6181, 'koKR', 'Pilna wiadomość', 'Choć od Wichrogrodu nie dostajemy bezpośrednio wielkiej pomocy, mam w mieście kontakt, który pomaga nam zaopatrywać się w pancerze. Nazywa się Osric Strang. Jego sklep, „Ograniczona Odporność”, jest na Starym Mieście w Wichrogrodzie.$B$BNasze zapasy pancerzy się kurczą i muszę poprosić Osrica o więcej. Zaniesiesz mu ten liścik?$B$BNajszybciej dostaniesz się do Wichrogrodu przez Thora, naszego mistrza gryfów. Jest zaraz u stóp wzgórza – zanieś mu mój liścik, a potem leć gryfem do Wichrogrodu.', 'Zanieś liścik Lewisa Thorowi, mistrzowi gryfów.', '', '', '', '', '', '', 0),
(8675, 'koKR', 'Nestor Niebogonik', '', '', '', '', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(9, 'koKR', 'Dobra robota, $gprzyjacielu:przyjaciółko;. Uczciwie $gzapracowałeś:zapracowałaś; na zapłatę. Kto wie, może Zachodni Skraj jeszcze kiedyś rozkwitnie.', 0),
(12, 'koKR', 'Dobra robota, $N. Mój zwiadowca widział twoje mężne czyny. Jak dotąd świetnie sobie radzisz.', 0),
(13, 'koKR', 'Twoje dotychczasowe mężne czyny potwierdziły twoją wartość dla Milicji Ludowej.', 0),
(14, 'koKR', 'Gdy opuściłem skażone ziemie Lordaeronu, zastałem w mojej ojczyźnie ponury stan rzeczy. Ale dla Zachodniego Skraju wciąż jest nadzieja. Męstwo, którego $gdowiodłeś:dowiodłaś; w walce, pokazuje mi jasno, że służysz naszej sprawie z honorem. Z wielką dumą przyjmuję cię w szeregi Milicji Ludowej. Niech Światło cię prowadzi.', 0),
(22, 'koKR', 'Są po prostu idealne, $N! Bardzo ci dziękuję. Dziś wieczorem urządzimy sobie z rolnikiem Saldeanem ucztę. A tu masz coś w podzięce za ciężką pracę. Chyba nie $gmyślałeś:myślałaś;, że pozwolę, żeby ktoś taki jak ty chodził głodny?', 0),
(36, 'koKR', 'Ta Verna zawsze była takim słodkim dziewczęciem. Będzie nam jej tu, w Zachodnim Skraju, brakowało, ale między nami mówiąc, w głębi duszy to miastowa dziewczyna i w Wichrogrodzie będzie jej w sam raz. Ale dość plotek! Teraz możemy ugotować gulasz z Zachodniego Skraju!', 0),
(38, 'koKR', 'Ta okra ładnie zagęści wywar! Teraz dodamy tylko łykowate mięso sępa, kilka oczu murloka i te pyszne ryje krwawokła. I gotowe! Za całą twoją pomoc, $N, weź pierwszą dzisiejszą porcję gulaszu z Zachodniego Skraju!', 0),
(48, 'koKR', 'Hep! Ho, ho!', 0),
(49, 'koKR', 'Hep! Ho, ho!', 0),
(50, 'koKR', 'Hep! Ho, ho!', 0),
(51, 'koKR', 'Hep! Ho, ho!', 0),
(53, 'koKR', 'W beczce leżakowany, przez węgiel cedzony,$Bprzez usta spływa wprost do duszy, uświęcony.$BWięc pijmy teraz – toast za ciebie wznoszę$Bi za mnie przy okazji, Grimbooze\'a Gromowara, proszę!', 0),
(64, 'koKR', 'Mój zegarek! Bardzo dziękuję, $gdobry panie:dobra pani;!$b$bJesteśmy tylko biednymi rolnikami i straciliśmy ziemię, ale przyjmij, proszę, tę nagrodę jako wyraz naszej wdzięczności.', 0),
(65, 'koKR', 'Więc to Mocnopłaszcz cię przysłał? No cóż, jestem mu coś winien.', 0),
(67, 'koKR', 'Stary kufer otwiera się ze skrzypnięciem...', 0),
(68, 'koKR', 'Ciekawe. Więc ten jegomość rzeczywiście spędził trochę czasu w Księżycowym Potoku. Dość dziwne, że list nigdy nie został doręczony. Tak czy inaczej, uzupełnię rejestr.', 0),
(102, 'koKR', 'Dobra robota, $N. Z tak dzielnymi poszukiwaczami przygód jak ty, walczącymi ramię w ramię z Milicją Ludową, Zachodni Skraj może znów stać się kwitnącym spichlerzem, jakim był kiedyś. Przyjmij, proszę, to w uznaniu twoich niestrudzonych wysiłków.', 0),
(103, 'koKR', 'Chwała ci, $N. Dzięki twojej ciężkiej pracy skały wybrzeża Zachodniego Skraju będą oświetlone. Dopóki płonie ogień, wiele istnień zostanie ocalonych.$B$BZginąłem na próżno na tym właśnie brzegu. Moją pośmiertną powinnością jest dopilnować, by nikt inny nie podzielił mojego losu.', 0),
(104, 'koKR', 'A więc ten plugawy poganin, Mętnooki, nie żyje. Dobra robota, $N. Twoimi rękami jedno życie dobiegło kresu, ale być może wiele innych zostało ocalonych. Wielkie Morze, choć pełne niebezpieczeństw, będzie tej nocy odrobinę bezpieczniejsze dzięki twojemu bohaterstwu.', 0),
(117, 'koKR', 'Chmiel i jęczmień, drożdże i słód,$bna kubki smakowe szturm – istny cud!$bNie trzeba błagać ani prosić wcale,$bbo Lager Gromowarów w baryłce – wspaniale!', 0),
(132, 'koKR', 'Ha! Powinienem był zostawić tego łajdaka, żeby zgnił, kiedy miałem okazję. Ale te informacje są bezcenne. Dobra robota.', 0),
(136, 'koKR', 'Kufer powoli otwiera się ze skrzypnięciem. Wygląda na to, że jest w nim tylko piasek i woda. Ale chwila! Wybiega z niego mały krab ze wskazówką do skarbu w szczypcach!', 0),
(138, 'koKR', 'Dobra robota, $gposzukiwaczu:poszukiwaczko; skarbów!', 0),
(139, 'koKR', 'Jesteś na dobrej drodze do fortuny, $gposzukiwaczu:poszukiwaczko; skarbów!', 0),
(140, 'koKR', 'Zawiasy starej skrzyni są zardzewiałe, ale wciąż działają. Siłą otwierasz skrzynię i zabierasz łupy.$B$BGratulacje!', 0),
(142, 'koKR', 'Oto niezbity dowód, że to VanCleef tu rządzi. Teraz musimy się tylko dowiedzieć, gdzie ukrywa się banda Nieskornych.$b$bPod twoją nieobecność dopisało nam szczęście. Złapaliśmy złodzieja, który próbował ukraść wóz Saldeana. W zamian za darowanie życia obiecał zaprowadzić nas do kryjówki. Chcę, żebyś $gbronił:broniła; zdrajcy, aby mógł wskazać kryjówkę. Gdy poznasz jej położenie, wróć do mnie.', 0),
(143, 'koKR', '$GDobry posłańcze:Dobra posłanniczko;, dobrze $gsłużyłeś:służyłaś; swojemu panu.', 0),
(144, 'koKR', 'Doprawdy, to wcale nie jest dobre. Nie zdawałem sobie sprawy, że położenie Mocnopłaszcza niewiele różni się od naszego tutaj, w Jeziernych Włościach. Cóż może być tak ważne, że Armia Wichrogrodu zostawia własny lud? Ech, nie powinienem rozmyślać na głos.$b$bProszę, $gposłańcze:posłanniczko;. Przyjmij te monety w zamian za twoją służbę dla gminy. Być może jeszcze cię wezwę.', 0),
(151, 'koKR', 'Bardzo ci dziękuję, $N! Biedna Stara Siwka będzie taka szczęśliwa!', 0),
(152, 'koKR', 'Dobra robota, $N. Masz prawdziwy talent do walki. Dzięki tobie wybrzeże Zachodniego Skraju jest bezpieczniejsze.', 0),
(153, 'koKR', 'Dobra robota. Przyjmij, proszę, jedną z tych rzeczy jako zapłatę za całą twoją ciężką pracę.', 0),
(155, 'koKR', 'Znakomicie, $N! Skoro wiemy, gdzie ukrywa się VanCleef, jest już praktycznie nasz.', 0),
(166, 'koKR', '$N, twoja odwaga jest godna podziwu. Milicja Ludowa dziękuje ci za służbę mieszkańcom Zachodniego Skraju. Śmierć VanCleefa oznacza początek końca Bractwa Nieskornych. Miejmy nadzieję, że wkrótce pokój znów zagości na równinach tej pięknej krainy.$B$BOddaję ci honory, $gpanie:pani;!', 0),
(184, 'koKR', 'Stokrotne dzięki, $N! Jak mówiłem, te strony nie nadają się już dla uczciwych ludzi, ale jak sytuacja się poprawi, to dzięki temu aktowi odzyskamy naszą ziemię.$b$bNie mam ci wiele do zaoferowania, ale proszę – weź to.', 0),
(214, 'koKR', 'Dobra robota, $N! W imieniu Milicji Ludowej oddaję ci honory za twoje wysiłki. Już niedługo, z pomocą tak dzielnych dusz jak ty, zwrócimy tę ziemię ludziom.', 0),
(1651, 'koKR', 'Udało się, $N! Dziękuję za pomoc. $GByłeś niesamowity:Byłaś niesamowita;. Nigdy nie myślałam, że ktoś może poradzić sobie z tyloma wrogami naraz.$B$BNaprawdę $gwykazałeś:wykazałaś; się odwagą wobec przytłaczającej przewagi.', 0),
(6181, 'koKR', 'Musisz dostarczyć ten liścik do Wichrogrodu? Żaden problem, możesz wziąć jednego z moich gryfów!', 0),
(11581, 'koKR', 'Zbezcześć wielkie ognisko Przymierza w Zachodnim Skraju!', 0),
(11583, 'koKR', 'Uczcij płomień Zachodniego Skraju!', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(9, 'koKR', 'O, widzę, że $gwróciłeś:wróciłaś;! Mam nadzieję, że ciężko $gpracowałeś:pracowałaś; przy oczyszczaniu pól z tych zbożowych wartowników. $GZniszczyłeś:Zniszczyłaś; już dwadzieścia?', 0),
(12, 'koKR', 'Może nie wyraziłem się jasno, $grekrucie:rekrutko;. Aby dowieść, że jesteś $ggodzien:godna; służby w Milicji Ludowej i w imię Światła, musisz zabić 15 traperów Nieskornych i 15 przemytników Nieskornych, a gdy to zrobisz, wrócić do mnie.', 0),
(13, 'koKR', 'Nie mamy czasu na rozmowy, $N. Łupieżcy Nieskornych odbierają mieszkańcom Zachodniego Skraju pokój i dobrobyt, na które zasługują. Dopilnuj, żeby zginęło co najmniej 15 łupieżców Nieskornych i 15 szabrowników Nieskornych. To będzie jasny sygnał, że zepsucie nie jest tu mile widziane.', 0),
(14, 'koKR', '$N, to nie czas na próżne pogawędki. Jeśli wciąż chcesz dowieść swojej wartości przed Milicją Ludową, musisz zabić Nieskornych, o których ci mówiłem. Wróć do mnie, gdy wypełnisz swój obowiązek.', 0),
(22, 'koKR', 'Do mojego słynnego placka z mięsem brakuje mi tylko 8 wątróbek krwawokła!', 0),
(36, 'koKR', 'Tak mi będzie brakowało Verny Furlbrow. Nie $gwidziałeś:widziałaś; jej przypadkiem po drodze?', 0),
(38, 'koKR', 'Przynieś mi takie składniki:$b$b3 łykowate mięsa sępa$b3 ryje krwawokła$b3 oczy murloka$b3 okry', 0),
(48, 'koKR', 'Hep! Ho, ho! Bis chcesz?$B$BTam, gdzie na południu winorośl się wije,$Bstudnia ukryta głęboko wodę kryje.$BCzysta jak Światła córa, co w bieli stoi –$Bprzynieś mi świętej wody źródlanej, co ducha koi.', 0),
(49, 'koKR', 'Bis? No pewnie!$B$BBursztyn – barwa mej najdłuższej miłości,$Bjak ostatni żar zmierzchu, gdy noc w niebie gości.$BBy miłość ma mogła doczekać się narodzenia,$Bprzynieś mi po worku żyta, kukurydzy i jęczmienia.', 0),
(50, 'koKR', 'Bis dla ciebie? No pewnie, $gprzyjacielu:przyjaciółko;!$B$BBędę mieszał i mieszał, aż zacier gotowy,$Bna nasz własny zapasik, tajny i domowy.$BZ mocnego metalu destylatora nam trzeba,$Bprzynieś srebrytu, a pieśń ma wzleci do nieba!', 0),
(51, 'koKR', 'Bis? Dla ciebie wszystko!$B$BŚwieżo pędzony, lecz jeszcze nie cedzony,$Bjak ugór zaorany, na ziarno spragniony.$BTeraz z węgla drzewnego stos przygotuję,$Bprzynieś mi gałąź jaworu – tego potrzebuję.', 0),
(53, 'koKR', 'Jasne, zaśpiewam ci to jeszcze raz, $gprzyjacielu:przyjaciółko;!$B$BPłyn słodki jak miód, jak łzy dziecka przejrzysty,$Bz latami nabiera barwy bursztynu, złocisty.$BLecz nim się upijemy, aż zaszumi w głowie,$Bbeczkę z dębu zwęglonego zbić trzeba – ja ci to mówię!', 0),
(64, 'koKR', 'Nie udało ci się chyba odzyskać mojego zegarka?', 0),
(68, 'koKR', 'A, pamiętam cię. To ty $gpytałeś:pytałaś; o tego Stalvana. $GZnalazłeś:Znalazłaś; w końcu to, czego $gszukałeś:szukałaś;?', 0),
(102, 'koKR', '$GZebrałeś:Zebrałaś; już 8 łap tych zdradzieckich gnoli?', 0),
(103, 'koKR', 'Bez oleju płomień długo się nie utrzyma, $N.', 0),
(104, 'koKR', '$GRozprawiłeś:Rozprawiłaś; się już z postrachem zwanym Starym Mętnookim? Widziano, jak krąży po wybrzeżu Zachodniego Skraju.$B$BWróć do mnie, gdy ta plugawa bestia będzie martwa.', 0),
(117, 'koKR', 'Pośpiesz się, $gprzyjacielu:przyjaciółko;, żwawo, bez zwłoki,$bby nasz lager miał smak pełny, głęboki.$bMniej jak gulasz, a bardziej jak piwo –$bpo chmiel ruszaj więc żwawo i żywo!', 0),
(132, 'koKR', 'Dobrze cię znowu widzieć, $N. Co Wiley miał na swoje usprawiedliwienie?', 0),
(142, 'koKR', '$N, $gzdobyłeś:zdobyłaś; jakieś informacje? $GOdnalazłeś:Odnalazłaś; posłańca?', 0),
(143, 'koKR', 'Witaj, $N. Co cię sprowadza do Milicji Ludowej?', 0),
(144, 'koKR', 'Czy możemy się wkrótce spodziewać Milicji Ludowej? Czy lord Mocnopłaszcz przysyła dobre wieści?', 0),
(151, 'koKR', 'Stara Siwka ledwo trzyma się na nogach. Udało ci się znaleźć dla niej trochę owsa?', 0),
(152, 'koKR', 'Zabij 7 łowców fal, 7 wojowników, 7 wyroczni i 7 przybrzeżników, a dopilnuję, żebyś $gzostał nagrodzony:została nagrodzona;.', 0),
(153, 'koKR', 'Przynieś mi 15 czerwonych skórzanych chust, a dobrze ci zapłacę.', 0),
(155, 'koKR', 'Z czym do mnie przychodzisz? Jestem bardzo zajętym człowiekiem...', 0),
(166, 'koKR', 'Jak idzie polowanie na Edwina VanCleefa?', 0),
(184, 'koKR', 'Masz akt własności mojej farmy?! To dobra wiadomość! Jakieś łobuzy ukradły go parę dni temu... Myślałem, że przepadł na dobre!$b$bOddaj mi go, proszę. Wynosimy się z Zachodniego Skraju i prędko tu nie wrócimy, ale jak już wrócimy, to te papiery będą nam potrzebne...', 0),
(214, 'koKR', '$GOdbijałeś:Odbijałaś; naszą ziemię z rąk bandy Nieskornych? Jeśli tak, pokaż mi 10 czerwonych jedwabnych chust jako dowód.', 0),
(6181, 'koKR', 'Wyglądasz, jakby ci się śpieszyło. No to $gtrafiłeś:trafiłaś; we właściwe miejsce!', 0);
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES
(235, 0, 'koKR', 'Witaj w naszych skromnych progach! Zawsze miło zobaczyć przyjazną twarz. I jakie masz silne ręce. Mąż i ja zawsze szukamy pomocy w gospodarstwie. Teraz, kiedy większość porządnych ludzi wyjechała, trudno o kogoś zdolnego do pracy.', 0),
(238, 0, 'koKR', 'Czasem myślę, że na niebie wisi wielka szara chmura i leje na nas samym pechem. Najpierw przegnali nas z naszej ziemi, a teraz nie możemy nawet wydostać się z Zachodniego Skraju. Wszystko się sypie. Trzeba coś z tym zrobić.', 0),
(239, 0, 'koKR', 'Przygody z bliska i z daleka,$bdziwaków pełno na świecie czeka.$bLecz gdy o coś zapytać mnie zechcesz,$bproste zadanie wykonać musisz jeszcze!', 0),
(392, 0, 'koKR', 'Nie lękaj się. Dawno już odszedłem z tego świata, ale nie chcę skrzywdzić nikogo z twojego ludu. Za życia widziałem zbyt wiele śmierci. Pragnę już tylko pokoju. Może pomożesz mi w mojej sprawie.', 0);
