INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(16, 'koKR', 'Do Czcigodnego Dyrektora Crilliana,\n\nMój dawny Mistrzu, piszę do Ciebie, abyś wiedział, czym ostatnio zajmuje się Twój uczeń. Idąc za Twoją radą, postanowiłem poszerzać wiedzę i mądrość, podróżując poza bramy naszego ukochanego Wichrogrodu. Moje wędrówki zawiodły mnie w wiele miejsc, lecz postanowiłem osiąść tutaj, w uroczym miasteczku Księżycowy Potok. Okoliczne pola Zachodniego Skraju są najpiękniejsze, gdy zbliżają się żniwa.', 0),
(17, 'koKR', 'Już po kilku dniach pobytu zacząłem udzielać lekcji miejscowym dzieciom z pobliskich gospodarstw. Lekcje szły tak dobrze, że burmistrz zlecił mi prowadzenie szkoły, a budowa zupełnie nowego budynku szkolnego już się rozpoczęła! Od Srebrzystego Boru przez Wichrogród aż po Księżycowy Potok – kto by pomyślał, że zobaczę taki kawał Azeroth!\n\nSerdeczne pozdrowienia,\n\nStalvan Mgłopłaszcz', 0),
(45, 'koKR', 'Dobra robota, kamracie! Teraz musisz iść prosto na wschód. Na wschód, w górę urwisk, na wschód, aż do drogi. Szukaj ruin starego komina przy drodze. Znajdziesz tam starą beczkę z następną wskazówką.', 0),
(46, 'koKR', 'A teraz od tej beczki zwróć się na północ. Idź prosto jak strzelił, aż zobaczysz pusty dzban przy samotnym wiatraku na nadmorskich urwiskach. Jak pogrzebiesz przy tym dzbanie, może znajdziesz to, czego szukasz.', 0),
(47, 'koKR', 'Skoro już znalazłeś mój stary dzban po whisky, skarb jest tuż-tuż! Od butelki zwróć się na zachód i zejdź na brzeg. Jak dojdziesz do wody, nie zatrzymuj się! Płyń prosto na zachód, aż znajdziesz wyspę z moją skrzynią ze skarbem!', 0),
(48, 'koKR', 'Blacknails – Morze na nas czeka. Potrzebujemy twoich zapasów z północy. Zdzieraj wszystko: każdy kolec z torów, każde wiadro. Potrzebujemy metalu. Miała przyjść dostawa od BB, ale spóźnia się już grubo. Nie zawiedź mnie, Blacknails. Tym razem wysyłaj zapasy prosto do „stodoły”. Nie ma czasu do stracenia. – VanCleef', 0),
(49, 'koKR', 'Lordzie Mocnopłaszczu – Gmina Jeziernych Włości uniżenie prosi o pomoc Twojej Milicji. W chwili, gdy to piszę, oblegają nas zarówno orkowie z Czarnej Skały, jak i gnole Cienioskórzy Morgantha. Nie prosiłbym o pomoc, gdyby nasze położenie nie było poważne. Czekamy na pomoc z Wichrogrodu, ale dopóki nie nadejdzie, błagam Cię o wsparcie. Gdy granice Królestwa zostaną przełamane, cała ludzkość znajdzie się w niebezpieczeństwie. Sędzia Solomon', 0),
(50, 'koKR', 'Wysoki Sędzio – Cały Zachodni Skraj opłakuje Wasze straty, lecz i nas nęka nasza własna wojna. Złodzieje i mechaniczne golemy przegnali rolników. Wichrogród wycofał swoje wojska, zostawiając ludzi bez obrony. Zebrałem Milicję Ludową po tym, jak Wichrogród nas porzucił, by ocalić to, co zostało z tej ziemi. Wysłanie Milicji do Rudej Grani oznaczałoby pewną zgubę dla Zachodniego Skraju. Z żalem, Gryan Mocnopłaszcz', 0),
(55, 'koKR', 'Oto akt własności rozległego terenu w regionie Zachodniego Skraju. Przyznaje on niżej wymienionym osobom prawo własności do wyznaczonego obszaru, a także do wszystkich wytworzonych na nim płodów i wszelkich budynków wzniesionych w jego granicach.$B$BDokument podpisali:$B$B    Theodore Furlbrow$B    Verna Furlbrow', 0),
(56, 'koKR', '[Poniższe słowa nabazgrano pośpiesznie na odwrocie aktu]$B$BPrzycisnęliśmy Furlbrowa i zabraliśmy mu akt. Pomyślałem, że się przyda, jakbyś chciał podrobić taki na własne gospodarstwo. Furlbrowowie nie będą nam robić kłopotów. Jak ich ostatnio widziałem, wynosili się z Zachodniego Skraju i utknęli z połamanym wozem.', 0),
(213, 'koKR', 'Gulasz z Zachodniego Skraju: 3 porcje łykowatego mięsa sępa, 3 ryje krwawokła, 3 oczy murloka, 3 okry. Wymieszać i zagotować. Przed podaniem dusić na wolnym ogniu co najmniej dwie godziny.', 0),
(1932, 'koKR', 'Strażniczka Egwina z biegiem lat stała się potężna i dzięki energiom Tirisfal znacznie przedłużyła sobie życie. W naiwnym przekonaniu, że na dobre pokonała Sargerasa, przez niemal dziewięćset lat chroniła świat przed sługami króla demonów. W końcu jednak Rada Tirisfal orzekła, że jej straż dobiegła końca.', 0),
(1933, 'koKR', 'Rada nakazała Egwinie powrót do Dalaranu, aby wybrać nowego następcę mocy Strażnika. Lecz Egwina, zawsze nieufna wobec Rady, postanowiła sama wybrać następcę.', 0),
(1934, 'koKR', 'Dumna Egwina postanowiła urodzić syna, któremu przekaże swoją moc. Nie zamierzała pozwolić, by Zakon Tirisfal manipulował jej następcą, tak jak próbował manipulować nią. Udała się do południowego królestwa Azeroth i znalazła tam idealnego ojca dla swojego syna: utalentowanego ludzkiego maga, Nielasa Arana.', 0),
(1935, 'koKR', 'Aran był nadwornym czarodziejem i doradcą króla Azeroth. Egwina uwiodła maga i poczęła z nim syna. Wrodzony talent Nielasa do magii miał głęboko zakorzenić się w nienarodzonym dziecku i wyznaczyć tragiczną drogę, którą to dziecko później obrało. W dziecku zaszczepiono też moc Tirisfal, lecz miała się ona obudzić dopiero, gdy osiągnie ono fizyczną dojrzałość.', 0),
(1936, 'koKR', 'Czas mijał i Egwina urodziła syna w ustronnym gaju. Nazwała chłopca Medivh, co w języku wysokich elfów oznacza „strażnik tajemnic”, i wierzyła, że wyrośnie na kolejnego Strażnika. Niestety złośliwy duch Sargerasa, ukryty w jej wnętrzu, opętał bezbronne dziecko, gdy jeszcze było w jej łonie. Egwina nie miała pojęcia, że najnowszy Strażnik świata jest już opętany przez jego największego wroga.', 0),
(1937, 'koKR', 'Pewna, że jej dziecko jest zdrowe i silne, Egwina oddała młodego Medivha na dwór Azeroth i zostawiła go tam, by wychowywali go jego śmiertelny ojciec i jego lud. Następnie odeszła w dzicz i przygotowała się na przejście w zaświaty, jakiekolwiek na nią czekały. Medivh wyrósł na silnego chłopca i nie miał pojęcia o potencjalnej mocy swojego dziedzictwa Tirisfal.', 0),
(1938, 'koKR', 'Sargeras czekał cierpliwie, aż moc młodzieńca się ujawni. Gdy Medivh był nastolatkiem, zdobył w Azeroth wielką popularność dzięki swoim magicznym umiejętnościom i często wyruszał na przygody z dwoma przyjaciółmi: Llane\'em, księciem Azeroth, i Anduinem Lotharem, jednym z ostatnich potomków rodu Arathi. Trzej chłopcy ustawicznie psocili w całym królestwie, lecz zwykli mieszkańcy bardzo ich lubili.', 0),
(1939, 'koKR', 'Gdy Medivh skończył czternaście lat, kosmiczna moc w jego wnętrzu przebudziła się i starła z wszechobecnym duchem Sargerasa czającym się w jego duszy. Medivh zapadł w stan katatonii, który trwał wiele lat.', 0),
(1940, 'koKR', 'Gdy ocknął się ze śpiączki, odkrył, że stał się dorosłym mężczyzną, a jego przyjaciele Llane i Anduin zostali władcami Azeroth. Choć pragnął użyć swojej niesamowitej, świeżo odkrytej mocy, by chronić ziemię, którą nazywał domem, mroczny duch Sargerasa wypaczył jego myśli i uczucia, kierując je ku podstępnemu celowi.', 0),
(1941, 'koKR', 'Sargeras upajał się mrocznym sercem Medivha, wiedział bowiem, że jego plany drugiej inwazji na świat są bliskie ukończenia i że to ostatni Strażnik świata doprowadzi je do skutku.', 0),
(2064, 'koKR', 'Po wielu długich miesiącach przygotowań Kel\'Thuzad i jego Kult Potępionych wreszcie zadali pierwszy cios, uwalniając na Lordaeron zarazę nieumarłych. Uther i jego bracia paladyni zbadali zarażone regiony w nadziei, że znajdą sposób na powstrzymanie zarazy. Mimo ich wysiłków zaraza wciąż się szerzyła i groziła rozbiciem Przymierza.', 0),
(2065, 'koKR', 'Gdy szeregi nieumarłych przetaczały się przez Lordaeron, jedyny syn Terenasa, książę Arthas, podjął walkę z Plagą. Arthasowi udało się zabić Kel\'Thuzada, lecz mimo to szeregi nieumarłych rosły z każdym żołnierzem, który padł w obronie ziemi. Sfrustrowany i bezradny wobec pozornie niepowstrzymanego wroga, Arthas sięgał po coraz bardziej skrajne środki, by go pokonać. W końcu towarzysze ostrzegli go, że traci swoje człowieczeństwo.', 0),
(2066, 'koKR', 'Strach i determinacja Arthasa okazały się jego ostateczną zgubą. Wytropił źródło zarazy aż w Północnej Grani, zamierzając raz na zawsze położyć kres zagrożeniu. Zamiast tego książę Arthas w końcu padł ofiarą przeogromnej mocy Króla Lisza. Wierząc, że ocali w ten sposób swój lud, Arthas sięgnął po przeklęte runiczne ostrze, Ostrze Mrozu.', 0),
(2067, 'koKR', 'Choć miecz dał mu niepojętą moc, odebrał mu też duszę i uczynił go największym z rycerzy śmierci Króla Lisza. Z odrzuconą duszą i strzaskanym umysłem Arthas poprowadził Plagę przeciwko własnemu królestwu. Ostatecznie zamordował własnego ojca, króla Terenasa, i zmiażdżył Lordaeron żelazną piętą Króla Lisza.', 0),
(3545, 'koKR', 'Kartkowanie kruszących się stronic księgi nie ujawnia niczego poza opisami życia na farmie Valganów. Odnotowano w niej zmiany pór roku, siewy i zbiory, a także narodziny i śmierci dzieci.$B$BZapiski urywają się nagle krótkim opisem zarazy. Żadne z opisanych dzieci nie mogło być na tyle dorosłe, by ukończyć szkolenie rycerskie – o ile którekolwiek w ogóle przeżyło zarazę.', 0),
(3546, 'koKR', 'Pierwsza połowa dziennika wydaje się być jedynie księgą rachunkową interesu pana Coopera. Ręcznie wypisane kolumny liczb odnotowują wyrób i sprzedaż beczek mieszkańcom Księżycowego Potoku, a nawet kilku klientom w samym Wichrogrodzie.$B$BDruga połowa księgi wygląda na osobisty dziennik pana Coopera, w którym pisze o przekazaniu rodzinnego interesu młodszemu bratu. Nie znajdujesz żadnej wzmianki o dzieciach.', 0);
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES
(50027, 'koKR', 'Czasem myślę, że na niebie wisi wielka szara chmura i leje na nas samym pechem. Najpierw przegnali nas z naszej ziemi, a teraz nie możemy nawet wydostać się z Zachodniego Skraju. Wszystko się sypie. Trzeba coś z tym zrobić.', '', '', '', '', '', '', '', '', '', '', '', '', '', '', ''),
(50034, 'koKR', 'Przygody z bliska i z daleka,$bdziwaków pełno na świecie czeka.$bLecz gdy o coś zapytać mnie zechcesz,$bproste zadanie wykonać musisz jeszcze!', 'Przygody z bliska i z daleka,$bdziwaków pełno na świecie czeka.$bLecz gdy o coś zapytać mnie zechcesz,$bproste zadanie wykonać musisz jeszcze!', '', '', '', '', '', '', '', '', '', '', '', '', '', '');
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(9, 'koKR', 'Chodź za mną, $n. Zaprowadzę cię do kryjówki Nieskornych. Ale lepiej mnie chroń, bo inaczej już po mnie.', '', 0),
(10, 'koKR', 'Wejście jest ukryte tutaj, w Księżycowym Potoku. Miej oczy szeroko otwarte, wszędzie mogą być złodzieje. Chcą mojej śmierci.', '', 0),
(11, 'koKR', 'Możesz przekazać Mocnopłaszczowi, że tu zaszyła się banda Nieskornych, $n.', '', 0),
(36, 'koKR', 'Kamieniarze... eee... Nieskorni, uwaga: zardzewiała kotwica tonie dziś w nocy.', '', 0),
(41, 'koKR', '', 'Na horyzoncie od strony wybrzeża zauważono ruchy Nieskornych. Na Wzgórzu Strażniczym spokój.', 0),
(42, 'koKR', 'Zgłoszono wzmożoną aktywność gnoli w Kamieniołomie Złotego Wybrzeża i w Kopalni Jangolode.', '', 0),
(43, 'koKR', 'Na Wzgórzu Strażniczym spokój, lordzie Mocnopłaszczu. Zgłoszono jednak duże ruchy Nieskornych w Księżycowym Potoku.', '', 0),
(54, 'koKR', '', 'Nie martw się, Stara Siwko, niedługo dostaniesz coś do jedzenia...', 0),
(55, 'koKR', '', 'Nigdy nie myślałam, że przyjdzie dzień, kiedy opuszczę mój rodzinny Zachodni Skraj...', 0),
(473, 'koKR', 'Giń w imię Edwina VanCleefa!', '', 0),
(474, 'koKR', 'Kto śmie wtrącać się w sprawy Bractwa Nieskornych? Giń, $N!', '', 0),
(475, 'koKR', 'Śmierć każdemu, kto stanie mi na drodze!', '', 0),
(476, 'koKR', 'Kto śmie drażnić posłańca Edwina VanCleefa? Giń!', '', 0),
(477, 'koKR', 'Czy mam jakieś listy, adresat: $n? Ależ skąd! Wygląda na to, że pora na twoją śmierć!', '', 0),
(478, 'koKR', 'Dostarczę cię, słabeuszu, prosto w zaświaty!', '', 0),
(479, 'koKR', 'Mam specjalną wiadomość, adresat: $n. Treść: masz zginąć!', '', 0),
(480, 'koKR', 'Śpiewający telegram, adresat: $n. Róże czerwone, fiołki fioletowe, każdego zabiję – i tobie utnę głowę!', '', 0),
(485, 'koKR', 'Pomocy!', '', 0),
(489, 'koKR', '$n, szybko nadchodzą! Szykuj się do walki!', '', 0),
(3092, 'koKR', 'Nie ukryjesz się przede mną, łotrzyku. Czuję twój strach.', '', 0),
(3093, 'koKR', 'A gdy jeden padnie, dwóch powstanie!', '', 0),
(3094, 'koKR', '%s gorączkowo kartkuje wielką księgę.', '', 0),
(3095, 'koKR', 'Cóż za słodka ironia – siły Wichrogrodu padają w obronie swojego miasta tylko po to, by powstać i walczyć u boku Bractwa jako narzędzia zagłady.', '', 0),
(3097, 'koKR', '%s przerzuca księgi.', '', 0),
(3098, 'koKR', 'Gdzie ja podziałem receptury Spółki Gitgeszeft?', '', 0),
(3126, 'koKR', 'Hej, Raven...', 'Hej, Raven...', 0),
(3127, 'koKR', 'No?', 'No?', 0),
(3128, 'koKR', 'Możemy zrobić sobie przerwę? Nogi mnie bolą jak diabli, a te... te stwory na dole przyprawiają mnie o gęsią skórkę.', 'Możemy zrobić sobie przerwę? Nogi mnie bolą jak diabli, a te... te stwory na dole przyprawiają mnie o gęsią skórkę.', 0),
(3129, 'koKR', 'Sama nie wiem, Jill. Jak Klaven zejdzie, kiedy będziemy się obijać, możemy skończyć jak jedno z tych stworzeń!', 'Sama nie wiem, Jill. Jak Klaven zejdzie, kiedy będziemy się obijać, możemy skończyć jak jedno z tych stworzeń!', 0),
(3130, 'koKR', '*Wzdycha* Pewnie masz rację, Raven. Wracam na patrol...', '*Wzdycha* Pewnie masz rację, Raven. Wracam na patrol...', 0),
(11544, 'koKR', 'Gdzie jest Nestor Zimokopyt?', 'Gdzie jest Nestor Zimokopyt?', 0),
(11545, 'koKR', 'Zimokopyt? Podobno używa życia w Łupieżczej Zatoce.', 'Zimokopyt? Podobno używa życia w Łupieżczej Zatoce.', 0),
(36040, 'koKR', 'Pomocy!', 'Pomocy!', 0);
